fields.InputDefinition:
{
  "goal": "Switch to the Knowledge Hub app (application switcher dropdown next to the logo) and click 'Feature Pipelines' in the left nav (fa-diagram-project icon). Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Then walk these surfaces IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) pipelines-list-search — confirm the pipelines screen renders as a card grid (each card showing target entity, output attribute, last-run status, and Run/Edit buttons) OR a clear empty-state inviting you to create a pipeline, then type into the 'Search by name, entity, or attribute…' box and confirm the card grid narrows to matching pipelines (or shows a 'No matching pipelines' state); (2) pipeline-editor-dialog — click the primary '+ New Pipeline' button in the header (or the 'Edit' button on an existing pipeline card) and confirm a modal dialog titled 'Feature Pipeline' opens containing the record-process editor form (you do NOT need to save); confirm it can be cancelled/closed. Keep going until both are done.",
  "startUrl": "http://localhost:4200/app/knowledge-hub",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "pipelines-list-search",
      "instruction": "Feature Pipelines list + search",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/knowledge-hub"
        }
      ],
      "visualCriteria": [
        "The Feature Pipelines screen renders a pipeline card grid OR a valid 'No feature pipelines yet' empty state, and typing in the search box narrows the cards to matches OR shows a 'No matching pipelines' no-results state"
      ]
    },
    {
      "name": "pipeline-editor-dialog",
      "instruction": "Feature Pipeline editor dialog",
      "visualCriteria": [
        "Clicking New Pipeline (or Edit on a card) opens a 'Feature Pipeline' modal dialog containing the record-process editor, and it can be closed/cancelled without error"
      ]
    }
  ]
}
